const SVG_NS='http://www.w3.org/2000/svg';const svgEl=(tag,attrs={})=>{const el=document.createElementNS(SVG_NS,tag);Object.entries(attrs).forEach(([k,v])=>el.setAttribute(k,String(v)));return el};
function nodeDimensions(n){let w=LOCAL.mode==='routine'?(n.kind==='block'?276:194):196;let h=LOCAL.mode==='routine'?(n.kind==='block'?54+Math.min(n.lines?.length||0,8)*17:69):70;return {w,h}}
function layoutGraph(g){const nodes=g.nodes.slice(0,800),all=new Map(nodes.map(n=>[n.id,n]));const indegree=new Map(nodes.map(n=>[n.id,0]));let adj=new Map(nodes.map(n=>[n.id,[]]));for(const e of g.edges){if(all.has(e.source)&&all.has(e.target)){indegree.set(e.target,indegree.get(e.target)+1);adj.get(e.source).push(e.target)}}
 const roots=nodes.filter(n=>!indegree.get(n.id)||n.id===g.entry||n.address===g.entry);
 const depths=new Map();const Q=[];for(const n of roots){depths.set(n.id,0);Q.push(n.id)}
 let count=0;while(Q.length && count<3000){count++;let id=Q.shift();const d=depths.get(id);for(const target of adj.get(id)||[]){if(!depths.has(target)){depths.set(target,Math.min(d+1,11));Q.push(target)}}}
 for(const n of nodes)if(!depths.has(n.id))depths.set(n.id,0);
 const layers=new Map();for(const n of nodes){const d=depths.get(n.id);if(!layers.has(d))layers.set(d,[]);layers.get(d).push(n)}
 const coords=new Map();const maxH=Math.max(...Array.from(layers.values()).map(x=>x.reduce((tot,n)=>tot+nodeDimensions(n).h+46,0)),300);
 for(const [d,items] of layers){let y=45;const total=items.reduce((tot,n)=>tot+nodeDimensions(n).h+46,0);y+=(maxH-total)/2;for(const n of items){let sz=nodeDimensions(n);coords.set(n.id,{x:36+d*(LOCAL.mode==='routine'?350:290),y,w:sz.w,h:sz.h});y+=sz.h+46}}
 return coords;}
function graphColor(n){if(n.kind==='vector')return '#aa91fd';if(n.kind==='dispatch')return '#f0ba6e';if(n.kind==='external'||n.kind==='unresolved')return '#e88b8b';if(n.kind==='call')return '#aa91fd';
 if(n.kind==='routine'){const a=annotation('R:'+n.address);return a.color||PALETTE[(LOCAL.state?.routines.findIndex(r=>r.entry===n.address)||0)%PALETTE.length]}
 const group=annotation('R:'+LOCAL.entry);return group.color||'#5ad4d2'}
function connectionPath(e){const a=LOCAL.graphGeom.get(e.source),b=LOCAL.graphGeom.get(e.target);if(!a||!b)return '';
 let x1=a.x+a.w,y1=a.y+a.h/2,x2=b.x,y2=b.y+b.h/2;
 if(x2<=x1+60){x1=a.x+a.w/2;y1=a.y+a.h;x2=b.x+b.w/2;y2=b.y;const mid=Math.max(y1,y2)+27;return `M${x1} ${y1} C${x1} ${mid},${x2} ${mid},${x2} ${y2}`}
 const bend=Math.max(55,(x2-x1)/2);return `M${x1} ${y1} C${x1+bend} ${y1},${x2-bend} ${y2},${x2} ${y2}`;
}
function refreshEdges(){const layer=$('#edgeLayer');layer.innerHTML='';if(!LOCAL.graph)return;
 const contained=new Set([...LOCAL.graphGeom.keys()]);for(const [ix,e] of LOCAL.graph.edges.entries()){
 if(!contained.has(e.source)||!contained.has(e.target))continue;const path=connectionPath(e);const call=e.kind.includes('call')||e.kind.includes('slot');const cond=e.kind.includes('taken')||e.kind.includes('not_taken');const unresolved=!e.proven && (e.kind.includes('indirect')||e.target.startsWith('X_UNRES'));const kind=unresolved?'unresolved':call?'call':cond?'conditional':'';
 const p=svgEl('path',{d:path,class:'flow-edge '+kind+(!e.proven?' inferred':''),'data-id':ix});const hit=svgEl('path',{d:path,class:'edge-click'});
 const title=svgEl('title');title.textContent=`${e.kind} · ${e.source} → ${e.target} · site $${e.site}`;hit.append(title);hit.addEventListener('click',event=>{event.stopPropagation();inspectEdge(e);$$('.flow-edge').forEach(q=>q.classList.remove('active'));p.classList.add('active')});layer.append(p,hit);
 }}
function renderGraph(){const g=LOCAL.graph;if(!g)return;LOCAL.renderedKey=graphKey();LOCAL.graphGeom=layoutGraph(g);const saved=LOCAL.graphLayouts[graphKey()]||{};for(const [id,geo] of LOCAL.graphGeom){const p=saved[id];if(p&&Number.isFinite(p.x)&&Number.isFinite(p.y)){geo.x=p.x;geo.y=p.y}}const layer=$('#nodeLayer');layer.innerHTML='';
 for(const n of g.nodes){const geo=LOCAL.graphGeom.get(n.id);if(!geo)continue;const col=graphColor(n),group=svgEl('g',{class:'flow-node'+(LOCAL.selectedNode===n.id?' selected':''),'data-id':n.id,transform:`translate(${geo.x},${geo.y})`});let frame=svgEl('rect',{class:'node-frame',x:0,y:0,width:geo.w,height:geo.h,rx:9,fill:'#172532',stroke:'#3b5062','stroke-width':1.2});group.append(frame);
 group.append(svgEl('rect',{x:0,y:0,width:4,height:geo.h,rx:2,fill:col}));group.append(svgEl('rect',{x:4,y:0,width:geo.w-4,height:37,rx:8,fill:'#1d3040'}));
 const header=svgEl('text',{class:'node-hdr',x:15,y:19});header.textContent=n.kind==='routine'?routineLabel(n.address):n.label;group.append(header);
 const sub=svgEl('text',{class:'node-sub',x:15,y:32});sub.textContent=n.subtitle||'';group.append(sub);
 if(n.lines?.length){n.lines.slice(0,8).forEach((line,k)=>{let t=svgEl('text',{class:'node-line',x:15,y:53+k*17});t.textContent=line.length>39?line.slice(0,38)+'…':line;group.append(t)});if(n.length>8){const t=svgEl('text',{class:'node-sub',x:15,y:geo.h-8});t.textContent=`+ ${n.length-8} more opcodes`;group.append(t)}}
 const title=svgEl('title');title.textContent=n.label+' / '+n.subtitle;group.append(title);group.addEventListener('pointerdown',ev=>{
 if(ev.button!==0)return;ev.stopPropagation();LOCAL.drag={type:'node',id:n.id,origin:{x:geo.x,y:geo.y},px:ev.clientX,py:ev.clientY,moved:false};$('#graphCanvas').setPointerCapture(ev.pointerId)
 });layer.append(group)}refreshEdges();fitGraph();const view=LOCAL.graphTransforms[graphKey()];if(view&&Number.isFinite(view.scale)&&Number.isFinite(view.x)&&Number.isFinite(view.y)){LOCAL.scale=view.scale;LOCAL.offset={x:view.x,y:view.y};applyTransform()}if(g.nodes.length>800)toast('Graph shows first 800 nodes; use routine mode to inspect full detail')}
function applyTransform(){const {x,y}=LOCAL.offset;$('#graphWorld').setAttribute('transform',`translate(${x},${y}) scale(${LOCAL.scale})`);txt('#zoomValue',Math.round(LOCAL.scale*100)+'%')}
function fitGraph(){if(!LOCAL.graphGeom.size)return;const all=[...LOCAL.graphGeom.values()];const xmin=Math.min(...all.map(x=>x.x)),ymin=Math.min(...all.map(x=>x.y)),xmax=Math.max(...all.map(x=>x.x+x.w)),ymax=Math.max(...all.map(x=>x.y+x.h));const r=$('#graphCanvas').getBoundingClientRect();const ww=Math.max(1,xmax-xmin),hh=Math.max(1,ymax-ymin);LOCAL.scale=Math.max(.07,Math.min(1.45,(r.width-80)/ww,(r.height-65)/hh));LOCAL.offset={x:(r.width-ww*LOCAL.scale)/2-xmin*LOCAL.scale,y:(r.height-hh*LOCAL.scale)/2-ymin*LOCAL.scale};applyTransform()}
function zoom(factor,p){const r=$('#graphCanvas').getBoundingClientRect();const cx=p?p.x-r.left:r.width/2,cy=p?p.y-r.top:r.height/2;const before=LOCAL.scale;LOCAL.scale=Math.max(.05,Math.min(3.5,LOCAL.scale*factor));LOCAL.offset={x:cx-(cx-LOCAL.offset.x)*LOCAL.scale/before,y:cy-(cy-LOCAL.offset.y)*LOCAL.scale/before};applyTransform()}
function explainOpcode(ins){
 const op=ins.op, arg=ins.operand||'', dst=op.endsWith('A')?'accumulator A':op.endsWith('B')?'accumulator B':op.endsWith('D')?'16-bit D (A:B)':op.endsWith('X')?'index X':op.endsWith('Y')?'index Y':'register';
 const place=arg.startsWith('#')?'the constant '+arg:arg.includes(',X')?'the address X + '+arg.split(',')[0]:arg.includes(',Y')?'the address Y + '+arg.split(',')[0]:arg?'memory '+arg:'the current register value';
 const branch={BRA:'Always jump',BRN:'Never take the jump',BNE:'Jump if the zero flag is clear (not equal)',BEQ:'Jump if the zero flag is set (equal)',BCC:'Jump if the carry flag is clear',BCS:'Jump if the carry flag is set',BHI:'Jump if unsigned higher',BLS:'Jump if unsigned lower or same',BPL:'Jump if negative flag is clear',BMI:'Jump if negative flag is set',BVC:'Jump if overflow is clear',BVS:'Jump if overflow is set',BGE:'Jump if signed greater or equal',BLT:'Jump if signed less',BGT:'Jump if signed greater',BLE:'Jump if signed less or equal',BRSET:'Jump when selected bits are set',BRCLR:'Jump when selected bits are clear'};
 if(branch[op])return branch[op]+'; target '+(ins.operand||'?')+'. The branch checks condition-code flags from earlier instructions.';
 if(op==='JMP')return 'Jump to '+place+' without saving a return address.';
 if(op==='JSR'||op==='BSR')return 'Call a subroutine at '+place+'; the CPU pushes its return address onto the stack.';
 if(op==='RTS')return 'Return from this subroutine by retrieving the saved return address from the stack.';
 if(op==='RTI')return 'Restore CPU registers and flags from the interrupt stack frame, then resume interrupted execution.';
 if(op==='SWI')return 'Software interrupt: transfer execution through the SWI vector.';
 if(op==='WAI')return 'Wait for an interrupt; execution pauses until an interrupt event.';
 if(op==='STOP')return 'Stop the CPU until an allowed wakeup event.';
 if(op==='NOP')return 'Do nothing except advance the program counter.';
 if(['LDAA','LDAB','LDD','LDX','LDY','LDS'].includes(op))return 'Load '+(op==='LDS'?'stack pointer':dst)+' from '+place+'.';
 if(['STAA','STAB','STD','STX','STY','STS'].includes(op))return 'Write '+(op==='STS'?'stack pointer':dst)+' to '+place+'.';
 if(op==='ABX'||op==='ABY')return 'Add unsigned accumulator B to index register '+op.slice(-1)+'.';
 if(op==='TSX'||op==='TSY')return 'Copy stack-pointer-relative address into '+op.slice(-1)+'.';
 if(op==='TXS'||op==='TYS')return 'Update the stack pointer from index '+op[1]+'.';
 if(op==='PSHA'||op==='PSHB'||op==='PSHX'||op==='PSHY')return 'Push '+dst+' onto the stack; stack pointer decreases.';
 if(op==='PULA'||op==='PULB'||op==='PULX'||op==='PULY')return 'Pull a saved value from stack into '+dst+'; stack pointer increases.';
 if(op==='INS')return 'Increment stack pointer by one byte (discard one stack byte).';
 if(op==='DES')return 'Decrement stack pointer by one byte (reserve one stack byte).';
 if(op==='MUL')return 'Multiply unsigned A × B; store the 16-bit product in D.';
 if(op==='IDIV')return 'Divide unsigned D by X; quotient goes into X and remainder into D.';
 if(op==='FDIV')return 'Fractional division using D and X; affects D and X.';
 if(op==='BSET'||op==='BCLR')return (op==='BSET'?'Set':'Clear')+' the selected flag bits in '+place+'.';
 if(op.startsWith('CMP')||op.startsWith('CP')||op==='CBA')return 'Compare register with '+place+' and update CPU condition flags without saving the subtraction result.';
 if(op.startsWith('BIT'))return 'Test selected bits from '+place+'; update flags without modifying the value.';
 if(op.startsWith('ADD')||op.startsWith('ADC')||op==='ABA')return 'Add '+place+' to '+dst+'; result wraps at the register width. Flags are updated.';
 if(op.startsWith('SUB')||op.startsWith('SBC')||op==='SBA')return 'Subtract '+place+' from '+dst+'; flags record carry/borrow, zero, sign and overflow.';
 if(op.startsWith('AND')||op.startsWith('ORA')||op.startsWith('EOR'))return 'Perform a bitwise logic operation using '+place+' and '+dst+'.';
 if(op.startsWith('INC')||op.startsWith('DEC'))return (op.startsWith('INC')?'Increase':'Decrease')+' the addressed register or memory value by one.';
 if(op==='CLI'||op==='SEI')return (op==='CLI'?'Enable':'Mask')+' normal maskable interrupts.';
 if(op==='CLC'||op==='SEC')return (op==='CLC'?'Clear':'Set')+' the carry flag.';
 if(op==='TAP')return 'Copy accumulator A into the condition-code register.';
 if(op==='TPA')return 'Copy condition-code flags into accumulator A.';
 if(op==='XGDX'||op==='XGDY')return 'Exchange D with index register '+op.slice(-1)+'.';
 if(op==='TAB'||op==='TBA')return 'Transfer one 8-bit accumulator into the other.';
 if(op.startsWith('LSR')||op.startsWith('ASL')||op.startsWith('ASR')||op.startsWith('ROL')||op.startsWith('ROR'))return 'Shift or rotate bits; carry and other condition flags can change.';
 return op+' '+arg+' — 68HC11 instruction; inspect its math/effects and register state for exact context.';
}
function explainEdge(e){
 const names={taken:'Branch condition true; execution jumps to the target block',not_taken:'Condition false; execution continues down the other path',fallthrough:'Normal execution continues with the next instruction',return_path:'Execution resumes here after the called subroutine returns',jump:'Unconditional transfer of execution',call:'Push return address and enter a subroutine',vector:'Interrupt/reset vector enters this routine',indirect_jump:'Jump destination depends on a register at runtime'};
 return names[e.kind]||(/slot/.test(e.kind)?'A possible table-selected routine; actual selection depends on the runtime index':/dispatch/.test(e.kind)?'Possible computed dispatcher relation':e.kind);
}
async function inspectFlowBlock(n){
 const key=LOCAL.entry;let r=LOCAL.routine;
 if(!r||r.entry!==key){try{r=await api('/api/routine',{entry:key})}catch(e){toast(e.message,true);return}}
 const start=parseInt(n.address,16),all=r.instructions,at=all.findIndex(i=>parseInt(i.pc,16)===start);
 if(at<0){selectAddress(n.address);return}
 let current=[];for(let k=at;k<all.length;k++){const i=all[k];if(k>at&&parseInt(i.pc,16)!==parseInt(all[k-1].pc,16)+all[k-1].bytes.split(' ').length)break;current.push(i);if(['BRA','JMP','RTS','RTI','STOP','JSR','BSR'].includes(i.op)||['BNE','BEQ','BCC','BCS','BHI','BLS','BMI','BPL','BGE','BLT','BGT','BLE','BVC','BVS','BRSET','BRCLR'].includes(i.op))break;if(current.length>=n.length)break}
 const outgoing=(LOCAL.graph?.edges||[]).filter(e=>e.source===n.id);
 const meanings=current.map(i=>'<div class="info-item"><button type="button" class="flow-ins" data-pc="'+esc(i.pc)+'">$'+esc(i.pc)+'</button> <strong>'+esc(i.op+' '+i.operand)+'</strong><div>'+esc(explainOpcode(i))+'</div>'+(i.math?'<div class="muted">Computed effect: '+esc(i.math)+'</div>':'')+'</div>').join('');
 $('#inspect').innerHTML='<div class="eyebrow">EXECUTION BLOCK · ENGLISH EXPLANATION</div><div class="inspect-addr">$'+esc(n.address)+'</div><p class="inspect-subtitle">'+current.length+' decoded instructions · '+esc(r.label)+'</p><div class="notice">This block executes sequentially until its last instruction redirects execution or reaches another block. Descriptions summarize HC11 semantics; actual branch decisions depend on live register and flag values.</div><div class="subheading">What the CPU does</div>'+meanings+'<div class="subheading">Where execution goes</div>'+(outgoing.map(e=>'<div class="info-item"><strong>'+esc(e.kind)+'</strong> → '+esc(e.target)+'<div>'+esc(explainEdge(e))+'</div></div>').join('')||'<div class="info-item">No outgoing edge decoded; return, stop, or unresolved control flow.</div>');
 $$('#inspect .flow-ins').forEach(b=>b.onclick=()=>selectInstruction(b.dataset.pc));showInspector();
}
function selectGraphNode(n){
 LOCAL.selectedNode=n.id;$$('.flow-node').forEach(x=>x.classList.toggle('selected',x.dataset.id===n.id));
 if(n.kind==='block')return inspectFlowBlock(n);
 if(n.kind==='routine'||n.kind==='call'&&n.address!=='?')return selectRoutine(n.address);
 if(n.kind==='dispatch')return selectTableByAddress(n.address);
 if(n.address&&n.address!=='?')return selectAddress(n.address);
 $('#inspect').innerHTML='<div class="eyebrow">UNRESOLVED CONTROL FLOW</div><h2>'+esc(n.label)+'</h2><div class="notice">This jump or call has no static destination. A register or dispatcher selects the destination during execution. Inspect the incoming edge to see the calling opcode.</div>';showInspector();
}
const SVG=$('#graphCanvas');SVG.addEventListener('wheel',ev=>{ev.preventDefault();zoom(Math.exp(-ev.deltaY*.001),{x:ev.clientX,y:ev.clientY});queueViewSave()},{passive:false});
SVG.addEventListener('pointerdown',ev=>{if(ev.button!==0||LOCAL.drag)return;LOCAL.drag={type:'pan',px:ev.clientX,py:ev.clientY,ox:LOCAL.offset.x,oy:LOCAL.offset.y};SVG.setPointerCapture(ev.pointerId)});
SVG.addEventListener('pointermove',ev=>{if(!LOCAL.drag)return;let d=LOCAL.drag;if(d.type==='pan'){LOCAL.offset={x:d.ox+ev.clientX-d.px,y:d.oy+ev.clientY-d.py};applyTransform()}
 else{const g=LOCAL.graphGeom.get(d.id);if(!g)return;g.x=d.origin.x+(ev.clientX-d.px)/LOCAL.scale;g.y=d.origin.y+(ev.clientY-d.py)/LOCAL.scale;if(Math.hypot(ev.clientX-d.px,ev.clientY-d.py)>4)d.moved=true;const el=$(`#nodeLayer g[data-id="${d.id}"]`);if(el)el.setAttribute('transform',`translate(${g.x},${g.y})`);refreshEdges()}});
SVG.addEventListener('pointerup',ev=>{if(LOCAL.drag){const d=LOCAL.drag;LOCAL.drag=null;try{SVG.releasePointerCapture(ev.pointerId)}catch(e){};if(d.type==='node'&&!d.moved){const node=LOCAL.graph?.nodes.find(n=>n.id===d.id);if(node)selectGraphNode(node)}queueViewSave()}});
function inspectEdge(e){LOCAL.inspectKind='edge';LOCAL.inspectData=e;$('#inspect').innerHTML=`<div class="eyebrow">CONTROL CONNECTION</div><h2 class="inspect-addr">${esc(e.kind)}</h2><p class="inspect-subtitle">$${esc(e.site)} · ${e.proven?'Resolved relationship':'Inferred / not proven'}</p><hr class="inspect-divider"><div class="info-item"><strong>From</strong> ${esc(e.source)}</div><div class="info-item"><strong>To</strong> ${esc(e.target)}</div><div class="notice">Control-flow edges are decoded from actual instructions. An inferred dispatch link does not prove that runtime execution selects that slot.</div><div class="inspect-actions"><button class="btn" id="edgeSite">Inspect call site</button><button class="btn" id="edgeTarget">Inspect target</button></div>`;
 $('#edgeSite').onclick=()=>selectInstruction(e.site);$('#edgeTarget').onclick=()=>{const tgt=e.target.replace(/^R|^X_|^T/,'');if(/^[0-9A-F]{4}$/.test(tgt))selectAddress(tgt)};showInspector();}
function showInspector(){$('.inspector').classList.add('visible')}
function renderInspectorWelcome(){$('#inspect').innerHTML='<div class="empty">Select a routine, instruction or byte address. User labels never change the binary.</div>'}
function annotationForm(key,obj={},headline='ROUTINE',detail=''){
 const value=annotation(key);let groups=romMeta().groups||[];const options=['Unsorted',...groups.filter(x=>x!=='Unsorted')];if(value.group&&!options.includes(value.group))options.push(value.group);
 return `<div class="eyebrow">${esc(headline)}</div><div class="inspect-addr">${esc(detail)}</div><hr class="inspect-divider"><div class="field"><label>Symbol / Label</label><input id="annLabel" value="${esc(value.label||'')}" placeholder="Name this ${esc(headline.toLowerCase())}"></div><div class="field-row"><div class="field"><label>Function group</label><input id="annGroup" value="${esc(value.group||'Unsorted')}" list="groupList"><datalist id="groupList">${options.map(x=>`<option value="${esc(x)}">`).join('')}</datalist></div><div class="field"><label>Color</label><select id="annColor"><option value="">Default</option>${PALETTE.map(c=>`<option value="${c}" ${value.color===c?'selected':''}>${c}</option>`).join('')}</select></div></div><div class="field"><label>Category / semantics</label><input id="annCategory" value="${esc(value.category||'')}" placeholder="e.g. Fuel / injector scheduling"></div><div class="field"><label>Definition / notes</label><textarea id="annNotes" placeholder="Explain evidence, inputs, outputs, side effects and constraints">${esc(value.notes||'')}</textarea></div><div class="field"><label>Flag bits (one per line: 7=Enabled)</label><textarea id="annFlags" style="height:72px" placeholder="7=Enable\n4=Trigger\n0=Status">${esc(value.flags||'')}</textarea></div><div class="field"><label>Derived math / interpretation (annotated)</label><textarea id="annMath" style="height:74px" placeholder="Explain numeric formula and units">${esc(value.math||'')}</textarea></div><button class="btn primary" style="width:100%" id="saveAnnotation">Save annotation</button>`;
}
function hookAnnotation(key){$('#saveAnnotation').onclick=async()=>{
 try{const value={label:$('#annLabel').value,group:$('#annGroup').value,color:$('#annColor').value,category:$('#annCategory').value,notes:$('#annNotes').value,flags:$('#annFlags').value,math:$('#annMath').value};await post('/api/annotation',{key,value});const grp=value.group;if(grp && !romMeta().groups.includes(grp))romMeta().groups.push(grp);LOCAL.state=await api('/api/state');updateStatus();renderTree();if(LOCAL.routine)LOCAL.routine.label=routineLabel(LOCAL.routine.entry);if(LOCAL.graph)renderGraph();toast('Annotation saved to this ROM’s workspace')}catch(e){toast(e.message,true)}}}
function inspectRoutine(entry){LOCAL.inspectKind='routine';LOCAL.inspectKey='R:'+entry;const r=LOCAL.routine,anno=annotation(LOCAL.inspectKey);const exits=r.exits.map(x=>`<span class="pill ${x.type.includes('indirect')?'warning':''}">$${esc(x.pc)} ${esc(x.type)}</span>`).join('');
 $('#inspect').innerHTML=annotationForm(LOCAL.inspectKey,anno,'ROUTINE','$'+entry)+`<hr class="inspect-divider"><div class="subheading">Execution metadata</div><div class="info-item"><strong>Entry evidence</strong><br>${r.sources.map(x=>`<span class="pill">${esc(x)}</span>`).join('')}</div><div class="info-item"><strong>Exit sites</strong><br>${exits||'No proven terminal'}</div><div class="info-item"><strong>Decoded starts</strong> ${r.instructions.length}</div><div class="info-item"><strong>Structure fingerprint</strong> <span class="mono">${r.signature}</span></div><div class="notice">This is a rooted routine view. Tail transfers, indirect jumps and interrupt-driven entry can prevent complete function boundaries from being proven.</div>`;
 hookAnnotation(LOCAL.inspectKey);showInspector();}
async function selectInstruction(pc){pc=hexa(pc);if(!LOCAL.routine||!LOCAL.routine.instructions.some(i=>i.pc===pc)){
 const candidate=LOCAL.state?.routines.find(r=>r.entry===pc);if(candidate){await selectRoutine(pc);return}
 return selectAddress(pc);
 }LOCAL.selectPc=pc;LOCAL.inspectKind='instruction';LOCAL.inspectKey='I:'+pc;const ins=LOCAL.routine.instructions.find(i=>i.pc===pc);LOCAL.inspectData=ins;
 $('#inspect').innerHTML=annotationForm(LOCAL.inspectKey,{},'INSTRUCTION','$'+pc)+`<div class="info-item mono"><strong>${esc(ins.bytes)}</strong> &nbsp;${esc(ins.op)} ${esc(ins.operand)}</div><div class="subheading">Straight-line math trace</div><pre>${esc(ins.math||'No arithmetic expression extracted')}</pre><div class="notice">A local symbolic sketch; no claim of global path-sensitive proof. Complex HC11 condition codes and memory aliasing require checking.</div><div class="subheading">Memory effects</div>${ins.accesses.map(x=>`<div class="info-item"><span class="pill ${x.access!=='R'?'warning':''}">${x.access}</span> <a href="#" class="addr-link" data-address="${x.address}">$${x.address}</a> ${esc(x.domain)}<br><span class="muted">${esc(x.resolution)} · ${esc(x.width_bits)} bits</span></div>`).join('')||'<div class="info-item">No explicit memory operand decoded</div>'}<div class="inspect-actions"><button id="jumpPC" class="btn">Show in ROM hex</button></div>`;
 hookAnnotation(LOCAL.inspectKey);$$('.addr-link').forEach(el=>el.onclick=ev=>{ev.preventDefault();if(el.dataset.address!=='?')selectAddress(el.dataset.address)});$('#jumpPC').onclick=()=>{LOCAL.hexStart=pc;focusTab('hex')};showInspector();highlightBottomPc(pc);
 api('/api/auto-reason',{pc}).then(d=>{if(LOCAL.inspectKey!=='I:'+pc||!d.instruction)return;const v=d.instruction;const div=$el('div','info-item');div.innerHTML='<div class="subheading">HC11 static register reasoning</div><div class="small-note">Before: '+esc(JSON.stringify(v.before))+'</div><div class="small-note">After: '+esc(JSON.stringify(v.after))+'</div><div class="small-note">Evidence: '+esc(v.reason)+'</div>'+v.memory.map(m=>'<div class="small-note">'+esc(m.direction)+' $'+esc(m.address)+' · '+esc(m.category)+' · '+esc(m.resolution)+'</div>').join('');$('#inspect').append(div)}).catch(()=>{});
}
async function selectAddress(addr){addr=hexa(addr);if(!/^[0-9A-F]{4}$/.test(addr))return;try{const data=await api('/api/address',{address:addr});LOCAL.inspectKind='address';LOCAL.inspectKey='A:'+addr;LOCAL.inspectData=data;
 $('#inspect').innerHTML=annotationForm(LOCAL.inspectKey,{},'MEMORY ADDRESS','$'+addr)+`<div class="inspect-subtitle">${esc(data.classification)}</div><div class="info-item"><strong>Memory zone</strong> ${esc(data.domain)}</div><div class="info-item mono"><strong>Bytes:</strong> ${esc(data.bytes)}</div><hr class="inspect-divider"><div class="subheading">Hardware / RAM / ROM cross-references</div><div class="info-item">${data.readers.length} reads · ${data.writers.length} writes · ${data.control_references.length} control references</div>${[...data.readers,...data.writers].slice(0,30).map(x=>`<div class="info-item"><span class="pill ${x.access==='R'?'':'warning'}">${x.access}</span><a href="#" class="addr-link" data-pc="${x.pc}">$${x.pc}</a> ${esc(x.instruction)} ${esc(x.operand)}<br><span class="muted">${esc(x.resolution)}</span></div>`).join('')||'<div class="info-item">No resolved accesses. Indexed addresses may be unresolved.</div>'}<div class="inspect-actions"><button class="btn" id="viewAddrHex">Hex view</button><button class="btn" id="makeTableHere">Define table</button></div>`;
 hookAnnotation(LOCAL.inspectKey);$$('.addr-link').forEach(el=>el.onclick=ev=>{ev.preventDefault();selectInstruction(el.dataset.pc)});$('#viewAddrHex').onclick=()=>{LOCAL.hexStart=addr;focusTab('hex')};$('#makeTableHere').onclick=()=>tableDialog({start:addr});showInspector();}
 catch(e){toast(e.message,true)}}
function inspectRegionBody(r){LOCAL.inspectKind='region';LOCAL.inspectData=r;$('#inspect').innerHTML=`<div class="eyebrow">ANNOTATED REGION</div><h2 class="inspect-addr">$${esc(r.start)}–$${esc(r.end)}</h2><p>${esc(r.label||r.type)}</p><p class="inspect-subtitle">${esc(r.type)} · ${esc(r.group)}</p><div class="notice">This is a user classification. It does not rewrite the decoded ROM.</div><div class="inspect-actions"><button class="btn" id="editRegionBtn">Edit</button><button class="btn" id="deleteRegionBtn">Delete</button></div>`;$('#editRegionBtn').onclick=()=>regionDialog(r);$('#deleteRegionBtn').onclick=async()=>{if(!confirm('Delete this region annotation?'))return;await post('/api/region/delete',{id:r.id});await refreshSummary(false);renderInspectorWelcome()};showInspector()}
